using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<TicketModelService>();

var app = builder.Build();

// Train the model at startup and register the prediction engine pool
var modelService = app.Services.GetRequiredService<TicketModelService>();
modelService.TrainAndEvaluate();

builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromFile(modelService.GetModelPath());

// Rebuild the app with the prediction pool registered
builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<TicketModelService>();
builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromFile(modelService.GetModelPath());

app = builder.Build();

// Train model (reuses cached model.zip if it exists, but we retrain for fresh metrics)
var svc = app.Services.GetRequiredService<TicketModelService>();
svc.TrainAndEvaluate();

app.MapControllers();
app.Run();

